/**
 * Fernet token tests.
 *
 * The first test pins a token generated by the *Python* reference implementation
 * (`relayx_analysis/relayx_license_server.py` → `fernet_encrypt`, same fixed timestamp and
 * IV) and verified with `cryptography.fernet.Fernet`: byte-for-byte equality here proves
 * the TS port is cross-language compatible, not merely self-consistent.
 */

import { describe, expect, it } from "vitest";

import { RELAYX_FERNET_SECRET } from "../src/config";
import { fernetDecrypt, fernetEncrypt, urlSafeBase64Encode } from "../src/fernet";

const PAYLOAD =
  '{"v":1,"type":"business","site_url":"https://panel.example.com","edition":"self-hosted","iat":1750000000}';
const IV = Buffer.from("00112233445566778899aabbccddeeff", "hex");
const TIMESTAMP = 1_750_000_000;

/** Produced by the Python reference with `iv = bytes.fromhex("00112233445566778899aabbccddeeff")`. */
const PYTHON_TOKEN =
  "gAAAAABoTuGAABEiM0RVZneImaq7zN3u_5o8bF2K7GsBXJJtxJU26cgyZE3RlOKMV2YorIAbXcVnrR5SG_bKdy3RRMQ8NIdH5k8fn-NuM5oJQLLmg6oQzZJ6QTaja4QbMxldN50lftEo03mSypjm0gqKd-ZC_hZrPtiCe88DeA3gafMlnnZkrE4sL2yqLn3_9vko3k8v-B7cDDwYd-pTifoN3DMzXPrd9w==";

describe("fernetEncrypt", () => {
  it("matches the Python reference token byte-for-byte", () => {
    const token = fernetEncrypt(RELAYX_FERNET_SECRET, Buffer.from(PAYLOAD, "utf8"), {
      timestamp: TIMESTAMP,
      iv: IV,
    });
    expect(token).toBe(PYTHON_TOKEN);
  });

  it("produces a token Python's cryptography.Fernet can decrypt", () => {
    // Cross-language check complement: same token, decrypted here with our own decoder.
    expect(fernetDecrypt(RELAYX_FERNET_SECRET, PYTHON_TOKEN).toString("utf8")).toBe(PAYLOAD);
  });

  it("uses a fresh random IV per call", () => {
    const first = fernetEncrypt(RELAYX_FERNET_SECRET, Buffer.from(PAYLOAD, "utf8"));
    const second = fernetEncrypt(RELAYX_FERNET_SECRET, Buffer.from(PAYLOAD, "utf8"));
    expect(first).not.toBe(second);
    expect(fernetDecrypt(RELAYX_FERNET_SECRET, first).toString("utf8")).toBe(PAYLOAD);
    expect(fernetDecrypt(RELAYX_FERNET_SECRET, second).toString("utf8")).toBe(PAYLOAD);
  });

  it("pads block-aligned plaintext with a full 16-byte block", () => {
    const aligned = "0123456789abcdef";
    const token = fernetEncrypt(RELAYX_FERNET_SECRET, Buffer.from(aligned, "utf8"));
    expect(fernetDecrypt(RELAYX_FERNET_SECRET, token).toString("utf8")).toBe(aligned);
  });

  it("rejects secrets that do not decode to 32 bytes", () => {
    expect(() => fernetEncrypt("AAAA", Buffer.from("x"))).toThrow(/32 字节/);
  });
});

describe("fernetDecrypt", () => {
  it("rejects a tampered token (HMAC check)", () => {
    const token = fernetEncrypt(RELAYX_FERNET_SECRET, Buffer.from(PAYLOAD, "utf8"), {
      timestamp: TIMESTAMP,
      iv: IV,
    });
    const corrupted = `${token.slice(0, 40)}${token[40] === "A" ? "B" : "A"}${token.slice(41)}`;
    expect(() => fernetDecrypt(RELAYX_FERNET_SECRET, corrupted)).toThrow(/HMAC|填充/);
  });

  it("rejects a token with the wrong version byte", () => {
    const token = fernetEncrypt(RELAYX_FERNET_SECRET, Buffer.from(PAYLOAD, "utf8"), {
      timestamp: TIMESTAMP,
      iv: IV,
    });
    const raw = Buffer.from(token.replace(/-/g, "+").replace(/_/g, "/"), "base64");
    raw[0] = 0x81;
    const broken = urlSafeBase64Encode(raw);
    expect(() => fernetDecrypt(RELAYX_FERNET_SECRET, broken)).toThrow(/版本字节|HMAC/);
  });
});
